"""Write the 27 cell configs of the final allocation grid from one template.

    python experiments/final_grid/make_cells.py

One file per cell keeps each arm's config loadable on its own; generating them
keeps the 26 fields they share byte-identical.
"""
from __future__ import annotations

from pathlib import Path

import yaml

CELLS_DIR = Path(__file__).resolve().parent / "cells"

REASONING = (0, 3000, 9000)     # thinking_token_budget
WRITE = (100, 300, 900)         # history_write_tokens
READ = (0, 4000, 9000)          # memory.retrieval_tokens

HEADER = """\
# Generated by experiments/final_grid/make_cells.py — edit the template there.
# One cell of the 3x3x3 allocation grid: reasoning budget x in-task write
# budget x cross-task read budget. Launch:
#   arloop-grid experiments/final_grid/cells/{name}.yaml --max-workers {workers}
"""


def cell(r: int, w: int, x: int) -> dict:
    """The full arm config for one (reasoning, write, read) cell."""
    name = f"final-grid-r{r}-w{w}-x{x}"
    # r9000 calls are long enough to exceed a 600 s client timeout, and the KV
    # cache holds fewer of the longer sequences, so the plane runs narrower
    workers, timeout_s = (10, 1800) if r == 9000 else (14, 600)
    cfg = {
        "name": name,
        "tasks": ["all"],
        "seeds": [0, 1, 2, 3, 4],
        "model": "qwen27b",
        "temperature": 0.5,
        "thinking": r > 0,
    }
    if r:
        cfg["thinking_token_budget"] = r
    cfg.update({
        "history_write_tokens": w,
        "chars_per_token": 3.5,
        "branch_policy": "best",
        "run_budget": {"type": "tokens", "limit": 100000},
        "exec_timeout_s": 900,
        "code_budget_chars": 30000,
        "sandbox": True,
    })
    if x:
        cfg["memory"] = {
            "bank": "final-loto-corpus",
            "embed_model": "Qwen/Qwen3-Embedding-0.6B",
            "reranker_model": "Qwen/Qwen3-Reranker-0.6B",
            "rerank_pool": 64,
            "rrf_k": 60,
            "retrieval_tokens": x,
            "loto": True,
        }
    cfg["ops"] = {
        "driver": {"max_workers": workers, "job_timeout_s": 43200,
                   "max_attempts": 2, "poll_s": 1.0},
        "loop": {"llm_retry_wall_s": 1800, "llm_retry_sleep_s": 30},
        "client": {"timeout_s": timeout_s, "max_retries": 4},
        "embedding": {"server": True, "device": "cuda"},
        "paths": {
            "traces_root": f"data/traces/{name}",
            "banks_root": "data/banks",
            "workspaces_root": f"data/workspaces/{name}",
            "data_env": {
                "ALE_DATA_DIR": "../arbench-pub/data/ale/public",
                "ALE_PRIVATE_DATA_DIR": "../arbench-pub/data/ale/private",
            },
        },
    }
    return cfg


def write_cells() -> list[Path]:
    """Write every cell yaml and return the paths, in grid order."""
    CELLS_DIR.mkdir(parents=True, exist_ok=True)
    written = []
    for r in REASONING:
        for w in WRITE:
            for x in READ:
                cfg = cell(r, w, x)
                path = CELLS_DIR / f"{cfg['name']}.yaml"
                header = HEADER.format(
                    name=cfg["name"],
                    workers=cfg["ops"]["driver"]["max_workers"])
                path.write_text(header + yaml.safe_dump(cfg, sort_keys=False))
                written.append(path)
    return written


if __name__ == "__main__":
    for path in write_cells():
        print(path.name)
